func (this *Bullish) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	// fetchTransfers
	//     {
	//         "requestId": "1",
	//         "toTradingAccountId": "111000000000001",
	//         "fromTradingAccountId": "121000000000001",
	//         "assetSymbol": "BTC",
	//         "quantity": "1.00000000",
	//         "status": "CLOSED",
	//         "statusReasonCode": "6002",
	//         "statusReason": "Executed",
	//         "createdAtTimestamp": "1621490985000",
	//         "createdAtDatetime": "2021-05-20T01:01:01.000Z"
	//     }
	//
	// transfer
	//     {
	//         "message": "Command acknowledged - TransferAsset",
	//         "requestId": "633909659774222336"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(transfer, "createdAtTimestamp")
	var currencyId *string = this.SafeString(transfer, "assetSymbol")
	var status *string = this.SafeString(transfer, "status")
	if status == nil {
		status = this.SafeString(transfer, "message")
	}
	return TransferEntryFromMap(map[string]any{
		"id":          this.SafeString(transfer, "requestId"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"currency":    this.SafeCurrencyCode(currencyId, currency),
		"amount":      this.SafeNumber(transfer, "quantity"),
		"fromAccount": this.SafeString(transfer, "fromTradingAccountId"),
		"toAccount":   this.SafeString(transfer, "toTradingAccountId"),
		"status":      this.ParseTransferStatus(status),
		"info":        transfer,
	})
}
func (this *Bullish) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"CLOSED":                               "ok",
		"OPEN":                                 "pending",
		"REJECTED":                             "failed",
		"Command acknowledged - TransferAsset": "ok",
	}
	return this.SafeString(statuses, status, status)
}

