func (this *Bullish) fetchBorrowRateHistoryBody(ch chan AsyncResult[[]map[string]any], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params

	r := <-promiseAll([]any{this.LoadMarketsAsync(), this.HandleTokenAsync()})
	if r.Err != nil {
		panic(r.Err)
	}

	r1 := <-this.LoadAccountAsync(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var tradingAccountId *string = SafeStringPtr(r1.Value)
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"assetSymbol":      currency["id"],
		"tradingAccountId": tradingAccountId,
	}
	var now int64 = this.Milliseconds()
	var startTimestamp any = since
	requestUntil, paramsUntil := this.HandleUntilOption("createdAtDatetime[lte]", request, params)
	var until any
	if derefPtr := this.SafeInteger(requestUntil, "createdAtDatetime[lte]"); derefPtr != nil {
		until = *derefPtr
	}
	// current endpoint requires both since and until parameters
	if since == nil {
		startTimestamp = now - (1000*60)*60*24*90 // Only the last 90 days of data is available for querying
	}
	if until == nil {
		until = now
	}
	request["createdAtDatetime[gte]"] = this.Iso8601(startTimestamp)
	request["createdAtDatetime[lte]"] = this.Iso8601(until)

	listEp3655 := <-this.PrivateGetV1HistoryBorrowInterest(this.Extend(request, paramsUntil))
	if listEp3655.Err != nil {
		panic(listEp3655.Err)
	}
	var response []any = listEp3655.Value

	//
	//     [
	//         {
	//             "assetId": "1",
	//             "assetSymbol": "BTC",
	//             "borrowedQuantity": "1.00000000",
	//             "totalBorrowedQuantity": "1.00000000",
	//             "createdAtDatetime": "2020-08-21T08:00:00.000Z",
	//             "createdAtTimestamp": "1621490985000"
	//         }
	//     ]
	//
	ch <- AsyncResult[[]map[string]any]{Value: MapSliceFromList(this.ParseBorrowRateHistory(response, code, since, limit))}
	return nil
}
