func (this *Bullish) HandleTokenAsync(optionalArgs ...any) <-chan AsyncResult[*string] {
	ch := make(chan AsyncResult[*string], 1)
	go this.handleTokenBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) handleTokenBody(ch chan AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var now int64 = this.Milliseconds()
	var token any = this.Token
	var tokenExpires *int64 = this.SafeInteger(this.Options, "tokenExpires")
	if (token == nil) || (tokenExpires == nil) || (now > *tokenExpires) {

		r := <-this.SignInAsync()
		if r.Err != nil {
			panic(r.Err)
		}
		var resolved *string
		switch resolvedBox := r.Value.(type) {
		case *string:
			resolved = resolvedBox
		case string:
			resolved = &resolvedBox
		default:
			_ = resolvedBox
		}
		ch <- AsyncResult[*string]{Value: resolved}
		return nil
	} else {

		var resolved1 *string
		switch resolved1Box := any(this.Token).(type) {
		case *string:
			resolved1 = resolved1Box
		case string:
			resolved1 = &resolved1Box
		default:
			_ = resolved1Box
		}
		ch <- AsyncResult[*string]{Value: resolved1}
		return nil
	}
}
func (this *Bullish) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	//
	//         {
	//             "type": "HttpInvalidParameterException",
	//             "message": "HTTP_INVALID_PARAMETER: '100m' is not a valid time bucket"
	//         }
	//
	//         {
	//             "message": "Order size outside valid range",
	//             "raw": null,
	//             "errorCode": 6023,
	//             "errorCodeName": "ORDER_SIZE_OUTSIDE_VALID_RANGE"
	//         }
	//
	var codeError *string = this.SafeString(response, "errorCode")
	var typeVar *string = this.SafeString(response, "type")
	if ((codeError != nil) && (codeError == nil || *codeError != "0") && (codeError == nil || *codeError != "1001")) || (typeVar != nil && *typeVar == "HttpInvalidParameterException") {
		var message any = ""
		var errorCodeName *string = this.SafeString(response, "errorCodeName")
		if errorCodeName != nil {
			message = errorCodeName
		} else {
			message = typeVar
		}
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], codeError, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBullish(userConfig map[string]any) *Bullish {
	p := newBullish()
	p.Init(userConfig)
	return p
}

func (this *Bullish) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

